UPDATE users_coupons
SET is_used = true,
    used_at = CURRENT_TIMESTAMP
WHERE coupon_id = #{couponId}
  AND user_id = #{userId}

mapper.select:
SELECT stock
FROM products
WHERE id = #{productId}

mapper.update:
UPDATE products
SET stock = stock - #{quantity}
WHERE id = #{productId}
  AND stock >= #{quantity}
